net.coobird.thumbnailator.resizers.Resizer expectedResizer = net.coobird.thumbnailator.resizers.Resizers.BICUBIC;
net.coobird.thumbnailator.resizers.ResizerFactory factory = new net.coobird.thumbnailator.resizers.FixedResizerFactory(expectedResizer);

java.awt.Dimension sourceDim = new java.awt.Dimension(1000, 1000);
java.awt.Dimension targetDim = new java.awt.Dimension(10, 10);
net.coobird.thumbnailator.resizers.Resizer actualResizer = factory.getResizer(sourceDim, targetDim);

assert actualResizer == expectedResizer : "Expected " + expectedResizer + " but got " + actualResizer;

System.out.println("__CHECK__ FixedResizerFactory " + actualResizer);

